raw_output:
SELECT Name, Level_of_membership, Age FROM visitor WHERE Level_of_membership > 4;

Group by:
SELECT Name, Level_of_membership, Age FROM visitor GROUP BY Name;

Order by:
SELECT Name, Level_of_membership, Age FROM visitor ORDER BY Name, Level_of_membership;

Limit:
SELECT Name, Level_of_membership, Age FROM visitor LIMIT 50;

